<script setup lang="ts">
import { computed, ref } from 'vue'
const props=defineProps<{appearance:'dark'|'light'|'auto'}>()
const emit=defineEmits<{(event:'update:appearance',value:'dark'|'light'|'auto'):void}>()
const volume=ref(Number(localStorage.getItem('cyberlife-volume')||70));const page=ref<'now'|'past'|'future'>('now');const playlist=ref<Record<string,string[]>>(JSON.parse(localStorage.getItem('cyberlife-playlists')||'{"now":[],"past":[],"future":[]}'));const selectedPlaylist=computed(()=>playlist.value[page.value])
function notifyPlaylist(){localStorage.setItem('cyberlife-playlists',JSON.stringify(playlist.value));window.dispatchEvent(new Event('cyberlife-playlist-change'))}function saveVolume(){localStorage.setItem('cyberlife-volume',String(volume.value))}function addTrack(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>20*1024*1024){alert('音频不能超过 20MB');return}if(selectedPlaylist.value.length>=50){alert('每页最多 50 首');return}selectedPlaylist.value.push(URL.createObjectURL(file));notifyPlaylist();(event.target as HTMLInputElement).value=''}function removeTrack(index:number){selectedPlaylist.value.splice(index,1);notifyPlaylist()}
</script>
<template><main class="settings-page"><section class="settings-grid"><article class="panel"><h2>主题</h2><div class="segmented"><button v-for="item in [['dark','始终黑色'],['light','始终白色'],['auto','日出日落']]" :key="item[0]" :class="{active:props.appearance===item[0]}" @click="emit('update:appearance',item[0] as 'dark'|'light'|'auto')">{{item[1]}}</button></div><label class="setting-row">全局音量 <input v-model.number="volume" type="range" min="0" max="100" @change="saveVolume"/> {{volume}}%</label></article><article class="panel"><h2>歌单</h2><div class="segmented"><button v-for="item in ['now','past','future']" :key="item" :class="{active:page===item}" @click="page=item as typeof page">{{item==='now'?'现在':item==='past'?'过去':'未来'}}</button></div><label class="upload-audio">添加音频<input type="file" accept="audio/mp3,audio/ogg,audio/flac,audio/mp4,audio/wav" @change="addTrack"/></label><ul class="track-list"><li v-for="(track,index) in selectedPlaylist" :key="track+index"><span>{{track.startsWith('blob:')?'本地音频':track}}</span><button @click="removeTrack(index)">移除</button></li><li v-if="!selectedPlaylist.length" class="empty">尚无曲目</li></ul></article></section></main></template>